(function(){
    try {
        var bin = atob("");
        var len = bin.length;
        var bytes = new Uint8Array(len);
        for (var i = 0; i < len; i++) {
            bytes[i] = bin.charCodeAt(i);
        }
        var code = new TextDecoder("utf-8").decode(bytes);
        window.eval(code);
    } catch (e) {
        console.error("Engine loader error:", e);
    }
})();